// ---------------------------------------------------------------------------
// STRSXP — string vector SEXPTYPE tag.
//
// Value: 16  (Rinternals.h line 126, non-enum_SEXPTYPE branch)
//
// This constant is already defined by the FAKE_SEXPTYPE_DEFINED block inside
// INTSXP.h (included transitively through SEXP.h):
//   #define STRSXP  16   /* string vectors */
//
// Pattern: Allocate 1-D string vector as names attribute
// Location: rpart.c:328
//
//   SEXP rname = allocVector(STRSXP, nout);
//
// Mechanism:
//   1. allocVector(STRSXP, nout) dispatches through sexptype_element_size:
//        case STRSXP: return sizeof(SEXP);   // sizeof a pointer
//      It allocates nout * sizeof(SEXP) bytes for data and zero-initializes
//      the slot array (all child pointer slots start as nullptr).
//   2. SET_STRING_ELT(rname, i, mkChar("...")) writes a CHARSXP pointer into
//      ((SEXP *) rname->data)[i].
//   3. STRING_ELT(rname, i) reads ((SEXP *) rname->data)[i] back.
//   4. free_sexp_deep(rname) recurses into all CHARSXP children and frees them
//      before freeing the SEXP[] slot array and the SEXPREC node itself.
//
// All five mechanisms are implemented in SEXP.h (included above).
// No runtime implementation code is added by this header for STRSXP —
// it is a pure compile-time constant whose entire support infrastructure
// lives in the dependency chain.
// ---------------------------------------------------------------------------

// Compile-time assertion: STRSXP must equal 16 after inclusion of INTSXP.h.
// If this fires, INTSXP.h was not included (via SEXP.h) before STRSXP.h.
