#ifndef FAKE_R_BLANKSTRING_DEFINED
#define FAKE_R_BLANKSTRING_DEFINED

// R_BlankString — the "" empty string as a CHARSXP sentinel.
// Real Rinternals.h line 470: LibExtern SEXP R_BlankString;
inline SEXP make_blank_string_charsxp() {
    // Static local: initialized once, survives for the process lifetime.
    // data points to a static char array — no heap allocation needed.
    static char blank_buf[] = "";
    static SEXPREC blank_rec = { CHARSXP, 0, 0, 1, static_cast<void *>(blank_buf) };
    return &blank_rec;
}

static SEXP R_BlankString = make_blank_string_charsxp();

#endif // FAKE_R_BLANKSTRING_DEFINED

#ifndef FAKE_R_BLANKSCALARSTRING_DEFINED
#define FAKE_R_BLANKSCALARSTRING_DEFINED

// R_BlankScalarString — the "" empty string as a length-1 STRSXP sentinel.
// Real Rinternals.h line 471: LibExtern SEXP R_BlankScalarString;
//
// The STRSXP data field holds a SEXP[1] child array pointing to
// R_BlankString (the CHARSXP above).  We store that child pointer in a
// static SEXP variable and point data at its address.
inline SEXP make_blank_scalar_string() {
    // Obtain the single CHARSXP child.
    static SEXP child = make_blank_string_charsxp();
    // The STRSXP data field must be a SEXP* (i.e. SEXP[1]).
    // Store the child pointer in a static so data has a stable address.
    static SEXP slot = child;
    static SEXPREC bss = { STRSXP, 1, 1, 1, static_cast<void *>(&slot) };
    return &bss;
}

static SEXP R_BlankScalarString = make_blank_scalar_string();

#endif // FAKE_R_BLANKSCALARSTRING_DEFINED

