#ifndef FAKE_MKCHARCEFAMILY_DEFINED
#define FAKE_MKCHARCEFAMILY_DEFINED

// cetype_t — character encoding type tag used by mkCharCE / mkCharLenCE.
// The real R_ext/Riconv.h defines this enum; the fake provides a minimal
// typedef so the stubs below compile without that header.
#ifndef FAKE_CETYPE_T_DEFINED
#define FAKE_CETYPE_T_DEFINED
typedef int cetype_t;
#endif

// Rf_mkCharCE — mkChar with explicit encoding tag; treat like mkChar in fake.
inline SEXP Rf_mkCharCE(const char *str, cetype_t /*enc*/) {
    return Rf_mkChar(str);
}

// Rf_mkCharLen — mkChar with explicit byte length (may contain embedded NUL).
// rpart does not use embedded-NUL strings; copy exactly len bytes + NUL.
inline SEXP Rf_mkCharLen(const char *str, int len) {
    SEXPREC *s = (SEXPREC *) malloc(sizeof(SEXPREC));
    if (!s) throw RError("mkCharLen: out of memory allocating SEXPREC node");
    s->type   = CHARSXP;
    s->length = len;
    s->nrow   = len;
    s->ncol   = 1;
    s->data   = malloc((size_t) len + 1);
    if (!s->data) {
        free(s);
        throw RError("mkCharLen: out of memory allocating string buffer");
    }
    memcpy(s->data, str, (size_t) len);
    static_cast<char *>(s->data)[len] = '\0';
    return s;
}

// Rf_mkCharLenCE — mkCharLen with encoding tag; ignore encoding in fake.
inline SEXP Rf_mkCharLenCE(const char *str, int len, cetype_t /*enc*/) {
    return Rf_mkCharLen(str, len);
}

// Rf_mkString — creates a length-1 STRSXP wrapping a single CHARSXP.
// Used in some rpart conditional paths; provide a correct implementation.
inline SEXP Rf_mkString(const char *str) {
    SEXP charsxp = Rf_mkChar(str);
    // Allocate a length-1 STRSXP to hold the child pointer.
    SEXPREC *s = (SEXPREC *) malloc(sizeof(SEXPREC));
    if (!s) {
        free_sexp_deep(charsxp);
        throw RError("mkString: out of memory allocating SEXPREC node");
    }
    s->type   = STRSXP;
    s->length = 1;
    s->nrow   = 1;
    s->ncol   = 1;
    s->data   = malloc(sizeof(SEXP));
    if (!s->data) {
        free(s);
        free_sexp_deep(charsxp);
        throw RError("mkString: out of memory allocating data buffer");
    }
    static_cast<SEXP *>(s->data)[0] = charsxp;
    return s;
}

#endif // FAKE_MKCHARCEFAMILY_DEFINED

