// ---------------------------------------------------------------------------
// --- ArenaFrame usage ---
//
// STRSXP allocations (allocVector(STRSXP, n)) are heap-managed via malloc()
// and are NOT arena-backed.  The STRSXP rname and its CHARSXP children must
// outlive the ArenaFrame because they are (notionally) part of the returned
// rlist VECSXP.
//
// However, rpart() — the only function that calls allocVector(STRSXP, ...) —
// also uses R_alloc/ALLOC for scratch arrays (rp.ydata, rp.xdata, savesort,
// etc.) during tree construction.  Those scratch allocations ARE arena-backed.
// Therefore, the .Call-entry wrapper for rpart() must declare ArenaFrame.
//
// Memory lifecycle for rname (STRSXP):
//   1. allocVector(STRSXP, nout) — malloc for SEXPREC node + malloc for
//      SEXP[nout] data array; all slots zero-initialized (nullptr).
//   2. SET_STRING_ELT(rname, i, mkChar("...")) — two malloc calls per element
//      (SEXPREC node + char buffer); may throw RError on failure.
//   3. Python caller extracts element count and string data by slot index.
//   4. Python caller calls free_sexp_deep(rname) to release all CHARSXP
//      children and the STRSXP node itself.  free_sexp_deep in SEXP.h
//      already handles STRSXP recursion:
//        if (s->type == VECSXP || s->type == EXPRSXP || s->type == STRSXP)
//            for each child: free_sexp_deep(child)
//
// Example .Call-entry wrapper (once fake_arena.h is available):
//
//   #include "fake_arena.h"
//   extern "C" SEXP rpart_entry(
//           SEXP ncat2, SEXP method2, SEXP opt2,
//           SEXP parms2, SEXP xvals2, SEXP xgrp2,
//           SEXP ymat2, SEXP xmat2, SEXP wt2, SEXP ny2, SEXP cost2) {
//       ArenaFrame _frame;   // frees R_alloc/ALLOC scratch at function exit
//       try {
//           return rpart(ncat2, method2, opt2, parms2, xvals2, xgrp2,
//                        ymat2, xmat2, wt2, ny2, cost2);
//       } catch (const RError &e) {
//           set_python_error(e.what());
//           return R_NilValue;
//       }
//   }
//
// Python reads the returned rlist by positional index (VECTOR_ELT):
//   rlist->data[0] == which3   (INTSXP)
//   rlist->data[1] == cptable3 (REALSXP)
//   rlist->data[2] == dsplit3  (REALSXP)
//   rlist->data[3] == isplit3  (INTSXP)
//   rlist->data[4] == dnode3   (REALSXP)
//   rlist->data[5] == inode3   (INTSXP)
//   rlist->data[6] == csplit3  (INTSXP, if catcount > 0)
//
// rname is attached via setAttrib (no-op in fake); Python does not need it.
// Both rlist and rname must be freed by Python after data extraction via
// free_sexp_deep(rlist) and free_sexp_deep(rname).
// ---------------------------------------------------------------------------

#endif // FAKE_STRSXP_H
